WITH rollup_totals AS (SELECT o.channel, src.status AS shipment_status, COUNT(*) AS num_rows, AVG(src.cost) AS avg_cost, GROUPING_ID() AS grouping_level FROM shipments src LEFT JOIN orders o ON src.order_id = o.id GROUP BY CUBE (o.channel, src.status)) SELECT channel, shipment_status, grouping_level, CASE WHEN shipment_status RLIKE '^(LOST|DELIVERED)$' THEN 'GROUP_B' WHEN shipment_status RLIKE '^(IN_TRANSIT|RETURNED)$' THEN 'OTHER_ZONE' ELSE 'CORE' END AS shipment_status_zone FROM rollup_totals ORDER BY channel DESC NULLS LAST;
